def fmt(x):
    if x is None:return '—'
    if isinstance(x,bool):return 'да' if x else 'нет'
    if isinstance(x,int):return str(x)
    if isinstance(x,float):return f'{x:.6f}'
    return str(x)

def table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(fmt(v).replace('|',', ') for v in r)+' |' for r in rows])+'\n'

